from typing import List, Any, Dict, Union, Optional, cast, TYPE_CHECKING

from pydantic import BaseModel, ConfigDict, Field, PrivateAttr, computed_field

if TYPE_CHECKING:
    from openai.types.chat import ChatCompletionMessageParam

from liquid import Environment, StrictUndefined, Undefined
from liquid.exceptions import UndefinedError
from .decorators.prompt_tracing import prompt_tracing
from .types import PromptData, Message


class PromptCompilationError(Exception):
    """Error class for template compilation issues"""

    def __init__(
        self, message: str, template: str, original_error: Optional[Exception] = None
    ):
        super().__init__(message)
        self.template = template
        self.original_error = original_error
        self.name = "PromptCompilationError"


# Type for template variables - supporting common data types
TemplateVariables = Dict[
    str, Union[str, int, float, bool, Dict[str, Any], List[Any], None]
]


class Prompt(PromptData):
    """
    A class representing a prompt configuration that can be used with OpenAI's API.
    Handles formatting messages with variables using Liquid templating.
    """

    _raw_data: Optional[PromptData] = PrivateAttr(default=None)

    def __init__(
        self,
        data: Union["PromptData", Dict[str, Any], None] = None,
        **kwargs: Any,
    ):
        if data is not None:
            if isinstance(data, BaseModel):
                init_kwargs = data.model_dump()
            elif isinstance(data, dict):
                init_kwargs = dict(data)
            else:
                init_kwargs = {}
            init_kwargs.update(kwargs)
            super().__init__(**init_kwargs)
            if isinstance(data, PromptData):
                self._raw_data = data.model_copy()
            else:
                self._raw_data = PromptData(**init_kwargs)
        else:
            super().__init__(**kwargs)
            self._raw_data = PromptData(**kwargs)

        # Set prompt default only if not provided (like TypeScript)
        if self.prompt is None:
            self.prompt = self._extract_system_prompt()

    @property
    def raw(self) -> PromptData:
        """Get the raw prompt data"""
        if self._raw_data is not None:
            return self._raw_data
        return PromptData(**self.model_dump())

    def _extract_system_prompt(self) -> str:
        """Extract system prompt from messages, like TypeScript version."""
        if self.messages:
            for message in self.messages:
                if message.role == "system":
                    return message.content
        return ""

    def _compile(self, variables: TemplateVariables, strict: bool) -> "CompiledPrompt":
        """
        Internal method to compile the prompt template with provided variables.
        """
        try:
            # Create environment based on strict mode
            env = Environment(undefined=StrictUndefined if strict else Undefined)

            # Compile main prompt
            compiled_prompt = ""
            if self.prompt:
                template = env.from_string(self.prompt)
                compiled_prompt = template.render(**variables)

            # Compile messages
            compiled_messages: List[Message] = []
            if self.messages:
                for message in self.messages:
                    template = env.from_string(message.content)
                    compiled_content = template.render(**variables)
                    compiled_message = Message(
                        role=message.role,
                        content=compiled_content,
                    )
                    compiled_messages.append(compiled_message)

            # Return simplified CompiledPrompt with variables preserved
            return CompiledPrompt(
                original=self,
                prompt=compiled_prompt,
                compiled_messages=compiled_messages,
                variables=variables.copy(),
            )

        except UndefinedError as error:
            template_str = self.prompt or str(self.messages)
            raise PromptCompilationError(
                f"Failed to compile prompt template: {str(error)}", template_str, error
            )
        except Exception as error:
            template_str = self.prompt or str(self.messages)
            raise PromptCompilationError(
                f"Failed to compile prompt template: {str(error)}", template_str, error
            )

    @prompt_tracing.compile
    def compile(
        self, variables: Optional[TemplateVariables] = None, **kwargs: Any
    ) -> "CompiledPrompt":
        """
        Compile the prompt template with provided variables (lenient - missing variables become empty).

        Args:
            variables: Dictionary containing variable values for template compilation
            **kwargs: Alternative way to pass variables as keyword arguments

        Returns:
            CompiledPrompt instance with compiled content
        """
        if variables is None:
            variables = {}

        # Merge explicit dict with kwargs, kwargs take precedence for conflicts
        merged_variables = {**variables, **kwargs}
        return self._compile(merged_variables, strict=False)

    @prompt_tracing.compile_strict
    def compile_strict(
        self, variables: Optional[TemplateVariables] = None, **kwargs: Any
    ) -> "CompiledPrompt":
        """
        Compile with validation - throws error if required variables are missing.

        Args:
            variables: Template variables

        Returns:
            CompiledPrompt instance with compiled content

        Raises:
            PromptCompilationError: If required variables are missing or compilation fails
        """
        if variables is None:
            variables = {}

        # Merge explicit dict with kwargs, kwargs take precedence for conflicts
        merged_variables = {**variables, **kwargs}
        return self._compile(merged_variables, strict=True)


class CompiledPrompt(BaseModel):
    """
    Represents a compiled prompt with compiled content and original variables
    """

    model_config = ConfigDict(arbitrary_types_allowed=True)

    original: Prompt = Field(repr=False)
    prompt: str
    compiled_messages: List[Message] = Field(repr=False)
    variables: TemplateVariables

    @computed_field  # type: ignore[prop-decorator]
    @property
    def messages(self) -> List[Dict[str, str]]:
        """
        Returns the compiled messages as a list of dicts compatible with OpenAI's API.
        """
        return [msg.model_dump() for msg in self.compiled_messages]

    def __getattr__(self, name: str) -> Any:
        """Delegate unknown attributes to original prompt for backward compatibility"""
        return getattr(self.original, name)

from typing import Any, Callable
import warnings
from functools import wraps
from langwatch.telemetry.tracing import LangWatchTrace, LangWatchSpan
from langwatch.telemetry.context import get_current_span as gcs, get_current_trace as gct

def _deprecated(func: Callable[[], Any]) -> Callable[[], Any]:
    @wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        warnings.warn(
            f"{func.__name__} is deprecated. Use langwatch.telemetry instead.",
            DeprecationWarning, stacklevel=2,
        )
        return func(*args, **kwargs)
    return wrapper

@_deprecated
def get_current_span():
    return gcs()

@_deprecated
def get_current_trace():
    return gct()

warnings.warn(
    "ContextSpan and ContextTrace are deprecated. Use LangWatchSpan from langwatch.telemetry.span and LangWatchTrace from langwatch.telemetry.tracing instead.",
    DeprecationWarning,
    stacklevel=2,
)

ContextSpan = LangWatchSpan
ContextTrace = LangWatchTrace

from types import ModuleType
from typing import (
    Any,
    AsyncGenerator,
    Dict,
    Generator,
    List,
    Optional,
    Set,
    Union,
    cast,
)

from langwatch.tracer import (
    ContextSpan,
    ContextTrace,
    get_current_trace,
)

from langwatch.domain import (
    ChatMessage,
    SpanInputOutput,
    SpanMetrics,
    TypedValueChatMessages,
    SpanParams,
    SpanTimestamps,
)
from langwatch.utils.utils import (
    milliseconds_timestamp,
    safe_get,
)
from langwatch.utils.capture import (
    capture_async_chunks_with_timings_and_reyield,
    capture_chunks_with_timings_and_reyield,
)

from litellm import CustomStreamWrapper
from litellm.types.utils import ModelResponse, Choices, StreamingChoices


class LiteLLMPatch:
    client: ModuleType
    trace: ContextTrace
    tracked_traces: Set[ContextTrace] = set()

    def __init__(
        self,
        client: ModuleType,
        trace: ContextTrace,
    ):
        self.trace = trace
        self.tracked_traces.add(self.trace)

        self.client = client

        if not hasattr(self.client, "_original_completion"):
            self.client._original_completion = self.client.completion  # type: ignore
            self.client._original_acompletion = self.client.acompletion  # type: ignore

            self.client.completion = self.patched_completion_create  # type: ignore
            self.client.acompletion = self.patched_completion_acreate  # type: ignore

    def patched_completion_create(self, *args, **kwargs):
        trace = None
        try:
            trace = get_current_trace()
        except:
            pass

        if not trace or trace not in self.tracked_traces:
            return cast(Any, self.client)._original_completion(*args, **kwargs)

        span = trace.span(type="llm").__enter__()

        started_at = milliseconds_timestamp()
        try:
            response: Union[ModelResponse, CustomStreamWrapper] = cast(
                Any, self.client
            )._original_completion(*args, **kwargs)

            if isinstance(response, CustomStreamWrapper):
                return capture_chunks_with_timings_and_reyield(
                    cast(Generator[ModelResponse, Any, Any], response),
                    lambda chunks, first_token_at, finished_at: LiteLLMPatch.handle_deltas(
                        span,
                        chunks,
                        SpanTimestamps(
                            started_at=started_at,
                            first_token_at=first_token_at,
                            finished_at=finished_at,
                        ),
                        **kwargs,
                    ),
                )
            else:
                finished_at = milliseconds_timestamp()
                LiteLLMPatch.handle_completion(
                    span,
                    response,
                    SpanTimestamps(started_at=started_at, finished_at=finished_at),
                    **kwargs,
                )
                return response
        except Exception as err:
            finished_at = milliseconds_timestamp()
            LiteLLMPatch.handle_exception(
                span,
                err,
                SpanTimestamps(started_at=started_at, finished_at=finished_at),
                **kwargs,
            )
            raise err

    async def patched_completion_acreate(self, *args, **kwargs):
        trace = None
        try:
            trace = get_current_trace()
        except:
            pass

        if not trace or trace not in self.tracked_traces:
            return await cast(Any, self.client)._original_acompletion(*args, **kwargs)

        span = trace.span(type="llm").__enter__()

        started_at = milliseconds_timestamp()

        try:
            response: Union[ModelResponse, CustomStreamWrapper] = await cast(
                Any, self.client
            )._original_acompletion(*args, **kwargs)

            if isinstance(response, CustomStreamWrapper):
                return capture_async_chunks_with_timings_and_reyield(
                    cast(AsyncGenerator[ModelResponse, Any], response),
                    lambda chunks, first_token_at, finished_at: LiteLLMPatch.handle_deltas(
                        span,
                        chunks,
                        SpanTimestamps(
                            started_at=started_at,
                            first_token_at=first_token_at,
                            finished_at=finished_at,
                        ),
                        **kwargs,
                    ),
                )
            else:
                finished_at = milliseconds_timestamp()
                LiteLLMPatch.handle_completion(
                    span,
                    response,
                    SpanTimestamps(started_at=started_at, finished_at=finished_at),
                    **kwargs,
                )
                return response
        except Exception as err:
            finished_at = milliseconds_timestamp()
            LiteLLMPatch.handle_exception(
                span,
                err,
                SpanTimestamps(started_at=started_at, finished_at=finished_at),
                **kwargs,
            )
            raise err

    @classmethod
    def handle_deltas(
        cls,
        span: ContextSpan,
        deltas: List[ModelResponse],
        timestamps: SpanTimestamps,
        **kwargs,
    ):
        # Accumulate deltas
        chat_outputs: Dict[int, List[ChatMessage]] = {}
        usage = None
        for delta in deltas:
            if hasattr(delta, "usage") and delta.usage is not None:  # type: ignore
                usage = delta.usage  # type: ignore
            for choice in delta.choices:
                choice = cast(StreamingChoices, choice)
                index = choice.index
                delta = choice.delta
                if delta.role:
                    chat_message: ChatMessage = {
                        "role": delta.role,
                        "content": delta.content,
                    }
                    if delta.function_call:
                        chat_message["function_call"] = {
                            "name": delta.function_call.name or "",
                            "arguments": delta.function_call.arguments or "",
                        }
                    if delta.tool_calls:
                        chat_message["tool_calls"] = [
                            {
                                "id": tool.id or "",
                                "type": tool.type or "",
                                "function": {
                                    "name": safe_get(tool, "function", "name") or "",
                                    "arguments": safe_get(tool, "function", "arguments")
                                    or "",
                                },
                            }
                            for tool in delta.tool_calls
                        ]
                    if index not in chat_outputs:
                        chat_outputs[index] = []
                    chat_outputs[index].append(chat_message)
                elif delta.function_call:
                    last_item = chat_outputs[index][-1]
                    if "function_call" in last_item and last_item["function_call"]:
                        current_arguments = last_item["function_call"].get(
                            "arguments", ""
                        )
                        last_item["function_call"]["arguments"] = current_arguments + (
                            delta.function_call.arguments or ""
                        )
                elif delta.tool_calls:
                    last_item = chat_outputs[index][-1]
                    if (
                        "tool_calls" in last_item
                        and last_item["tool_calls"]
                        and len(last_item["tool_calls"]) > 0
                    ):
                        for tool in delta.tool_calls:
                            last_item["tool_calls"][tool.index]["function"][
                                "arguments"
                            ] = last_item["tool_calls"][tool.index]["function"].get(
                                "arguments", ""
                            ) + (
                                safe_get(tool, "function", "arguments") or ""
                            )
                elif delta.content:
                    chat_outputs[index][-1]["content"] = (
                        chat_outputs[index][-1].get("content", "") or ""
                    ) + delta.content

        LiteLLMPatch.end_span(
            span=span,
            outputs=[
                TypedValueChatMessages(type="chat_messages", value=output)
                for output in chat_outputs.values()
            ],
            metrics=(
                SpanMetrics(
                    prompt_tokens=safe_get(usage, "prompt_tokens"),
                    completion_tokens=safe_get(usage, "completion_tokens"),
                    reasoning_tokens=safe_get(
                        usage, "completion_tokens_details", "reasoning_tokens"
                    ),
                )
                if usage
                else SpanMetrics()
            ),
            timestamps=timestamps,
            **kwargs,
        )

    @classmethod
    def handle_completion(
        cls,
        span: ContextSpan,
        response: ModelResponse,
        timestamps: SpanTimestamps,
        **kwargs,
    ):
        LiteLLMPatch.end_span(
            span=span,
            outputs=[
                TypedValueChatMessages(
                    type="chat_messages",
                    value=[
                        cast(
                            ChatMessage,
                            cast(Choices, output).message.model_dump(
                                exclude_unset=True
                            ),
                        )
                    ],
                )
                for output in response.choices
            ],
            metrics=SpanMetrics(
                prompt_tokens=safe_get(response, "usage", "prompt_tokens"),
                completion_tokens=safe_get(response, "usage", "completion_tokens"),
                reasoning_tokens=safe_get(
                    response, "usage", "completion_tokens_details", "reasoning_tokens"
                ),
            ),
            timestamps=timestamps,
            **kwargs,
        )

    @classmethod
    def handle_exception(
        cls,
        span: ContextSpan,
        err: Exception,
        timestamps: SpanTimestamps,
        **kwargs,
    ):
        LiteLLMPatch.end_span(
            span=span,
            outputs=[],
            metrics=SpanMetrics(),
            timestamps=timestamps,
            error=err,
            **kwargs,
        )

    @classmethod
    def end_span(
        cls,
        span: ContextSpan,
        outputs: List[SpanInputOutput],
        metrics: SpanMetrics,
        timestamps: SpanTimestamps,
        error: Optional[Exception] = None,
        **kwargs,
    ):
        output: Optional[SpanInputOutput] = (
            None
            if len(outputs) == 0
            else outputs[0] if len(outputs) == 1 else {"type": "list", "value": outputs}
        )
        span_params = SpanParams()
        params = [
            "frequency_penalty",
            "logit_bias",
            "logprobs",
            "top_logprobs",
            "max_tokens",
            "n",
            "presence_penalty",
            "seed",
            "stop",
            "stream",
            "temperature",
            "top_p",
            "tools",
            "tool_choice",
            "parallel_tool_calls",
            "functions",
            "user",
            "response_format",
            "reasoning_effort",
        ]
        for param in params:
            if kwargs.get(param):
                span_params[param] = kwargs.get(param, None)

        span.end(
            model=kwargs.get("model", "unknown"),
            input=TypedValueChatMessages(
                type="chat_messages", value=kwargs.get("messages", []).copy()
            ),
            output=output,
            error=error,
            params=span_params,
            metrics=metrics,
            timestamps=timestamps,
        )

        cls._prompts_path = None
        cls._registered_instrumentors.clear()

    @classmethod
    def reset_for_testing(cls) -> None:
        """Reset the singleton instance for testing purposes."""
        cls._reset_instance()

    @classmethod
    def get_singleton_instance(cls) -> Optional["Client"]:
        """Get the singleton instance for testing purposes."""
        return cls._instance

    @property
    def is_initialized(self) -> bool:
        """Check if this instance has been initialized for testing purposes."""
        return hasattr(self, "_initialized") and self._initialized

    @property
    def debug(self) -> bool:
        """Get the debug flag for the client."""
        return Client._debug

    @debug.setter
    def debug(self, value: bool) -> None:
        """Set the debug flag for the client."""
        Client._debug = value

    @property
    def endpoint_url(self) -> str:
        """Get the endpoint URL for the client."""
        return Client._endpoint_url

    @property
    def flush_on_exit(self) -> bool:
        """Get the flush on exit flag for the client."""
        return Client._flush_on_exit

    @property
    def api_key(self) -> str:
        """Get the API key for the client."""
        return Client._api_key

    @api_key.setter
    def api_key(self, value: str) -> None:
        """Set the API key for the client."""
        if value == Client._api_key:
            return

        previous_key = Client._api_key
        Client._api_key = value

        if previous_key and not Client._skip_open_telemetry_setup:
            self.__shutdown_tracer_provider()

            if not Client._is_dedicated_provider:
                # HACK: set global tracer provider to a proxy tracer provider back
                opentelemetry.trace._TRACER_PROVIDER = None  # type: ignore
                opentelemetry.trace._TRACER_PROVIDER_SET_ONCE = Once()  # type: ignore

        # Ensure provider/exporter exist after setting the key
        if (
            value
            and not Client._disable_sending
            and not Client._skip_open_telemetry_setup
        ):
            self.__setup_tracer_provider()

        if value:
            self._setup_rest_api_client()

    @property
    def disable_sending(self) -> bool:
        """Get whether sending is disabled."""
        return Client._disable_sending

    @property
    def rest_api_client(self) -> LangWatchApiClient:
        """Get the REST API client for the client."""
        if Client._rest_api_client is None:
            raise RuntimeError(
                "REST API client not initialized. Call _setup_rest_api_client() first."
            )
        return Client._rest_api_client

    @property
    def skip_open_telemetry_setup(self) -> bool:
        """Get whether OpenTelemetry setup is skipped."""
        return Client._skip_open_telemetry_setup

    @property
    def prompts_path(self) -> Optional[str]:
        """Get the base path for local prompt files."""
        return Client._prompts_path

    @disable_sending.setter
    def disable_sending(self, value: bool) -> None:
        """Set whether sending is disabled. Spans are still created; the exporter conditionally drops them."""
        if Client._disable_sending == value:
            return

        # force flush the tracer provider before changing the disable_sending flag
        if Client._tracer_provider and not Client._skip_open_telemetry_setup:
            Client._tracer_provider.force_flush()

        Client._disable_sending = value

    def acquire_disable_sending(self) -> None:
        """Refcount-based gate used by `langwatch.trace(disable_sending=True)`.

        Each call increments the refcount and forces sending disabled. Pairs
        with `release_disable_sending`. Concurrency-safe (issue #3981): an
        overlapping default-sending trace will not flip the flag back on
        while another trace still holds the disable refcount.
        """
        with Client._disable_sending_lock:
            if Client._disable_sending_refcount == 0:
                Client._disable_sending_user_baseline = Client._disable_sending
            Client._disable_sending_refcount += 1
            if not Client._disable_sending:
                # Bypass the public setter's force_flush — we want to start
                # dropping spans immediately, not flush pending traffic that
                # was queued under the prior baseline.
                Client._disable_sending = True

    def release_disable_sending(self) -> None:
        """Pair with `acquire_disable_sending`. Decrement the refcount; when
        it returns to zero, restore the user-set baseline value.
        """
        with Client._disable_sending_lock:
            if Client._disable_sending_refcount == 0:
                # Already released — defensive no-op; an unbalanced release
                # should not corrupt the baseline.
                return
            Client._disable_sending_refcount -= 1
            if Client._disable_sending_refcount == 0:
                baseline = Client._disable_sending_user_baseline
                if Client._disable_sending != baseline:
                    if (
                        Client._tracer_provider
                        and not Client._skip_open_telemetry_setup
                    ):
                        Client._tracer_provider.force_flush()
                    Client._disable_sending = baseline

    def __shutdown_tracer_provider(self) -> None:
        """Shuts down the current tracer provider, including flushing."""
        if not self._tracer_provider:
            return

        if Client._is_dedicated_provider:
            self.__detach_langwatch_processor()
            return

        if self._flush_on_exit:
            try:
                atexit.unregister(self._tracer_provider.force_flush)
            except ValueError:
                pass  # atexit handler was never registered or already unregistered

        force_flush = getattr(self._tracer_provider, "force_flush", None)
        if callable(force_flush):
            if self._debug:
                logger.debug("Forcing flush of tracer provider before shutdown.")
            force_flush()

        if Client._debug:
            logger.debug("Shutting down tracer provider.")
        if Client._tracer_provider is not None:
            Client._exporter_attached_providers.discard(id(Client._tracer_provider))
            Client._tracer_provider.shutdown()
        Client._tracer_provider = None

    def __detach_langwatch_processor(self) -> None:
        """Remove and shut down only our processor from a user-owned provider."""
        if Client._langwatch_processor is not None:
            Client._langwatch_processor.force_flush()
            Client._langwatch_processor.shutdown()
            try:
                multi = Client._tracer_provider._active_span_processor  # type: ignore[union-attr]
                old = Client._langwatch_processor
                multi._span_processors = tuple(
                    p for p in multi._span_processors if p is not old
                )
            except AttributeError:
                if Client._debug:
                    logger.debug("Could not access provider internals to remove processor")
            Client._langwatch_processor = None
        if Client._tracer_provider is not None:
            Client._exporter_attached_providers.discard(id(Client._tracer_provider))

    def __uninstrument_from_old_provider(self) -> None:
        """Uninstrument all instrumentors so they can be re-registered
        against a new provider. OTel instrumentors no-op on instrument()
        if already instrumented, so uninstrument must be called first."""
        old_provider = Client._tracer_provider
        if old_provider in Client._registered_instrumentors:
            for instrumentor in Client._registered_instrumentors[old_provider]:
                try:
                    instrumentor.uninstrument()
                except Exception:
                    if Client._debug:
                        logger.debug(f"Failed to uninstrument {instrumentor}")
            del Client._registered_instrumentors[old_provider]

    def __setup_tracer_provider(self) -> None:
        """Sets up the tracer provider if not already active."""
        if Client._skip_open_telemetry_setup:
            if Client._debug:
                logger.debug("Skipping tracer provider setup as requested.")
            return

        if not Client._tracer_provider:
            if Client._debug:
                logger.debug("Setting up new tracer provider.")
            Client._tracer_provider = self.__ensure_otel_setup()
            return

        if Client._is_dedicated_provider and id(Client._tracer_provider) not in Client._exporter_attached_providers:
            if Client._debug:
                logger.debug("Re-attaching LangWatch exporter to dedicated provider.")
            self.__set_langwatch_exporter(Client._tracer_provider)
            return

        if Client._debug:
            logger.debug("Tracer provider already active, not setting up again.")

    def __ensure_otel_setup(
        self, tracer_provider: Optional[TracerProvider] = None
    ) -> TracerProvider:
        if Client._is_dedicated_provider:
            dedicated = tracer_provider or Client._tracer_provider
            if dedicated is not None:
                self.__set_langwatch_exporter(dedicated)
                return dedicated
            return self.__create_new_tracer_provider()

        settable_tracer_provider = (
            tracer_provider or self.__create_new_tracer_provider()
        )

        try:
            global_provider = trace.get_tracer_provider()
            if isinstance(global_provider, trace.ProxyTracerProvider):
                trace.set_tracer_provider(settable_tracer_provider)
                return settable_tracer_provider

            if isinstance(global_provider, TracerProvider):
                if not self._ignore_global_tracer_provider_override_warning:
                    logger.warning(
                        "An existing global tracer provider was found. Attaching LangWatch exporter to the existing provider. Set `ignore_global_tracer_provider_override_warning=True` to suppress this warning."
                    )
                self.__set_langwatch_exporter(global_provider)
                return global_provider
            else:
                if Client._debug:
                    logger.debug(
                        "Global tracer provider is not an SDK TracerProvider; creating/using a new provider for LangWatch exporter."
                    )
                self.__set_langwatch_exporter(settable_tracer_provider)
                return settable_tracer_provider

        except Exception as e:
            raise RuntimeError(
                f"Failed to setup OpenTelemetry tracer provider: {e}"
            ) from e

    def __create_new_tracer_provider(self) -> TracerProvider:
        try:
            resource = Resource.create(Client._base_attributes)
            sampler = ALWAYS_OFF if Client._disable_sending else TraceIdRatioBased(1.0)
            provider = TracerProvider(resource=resource, sampler=sampler)

            # Only set up LangWatch exporter if sending is not disabled
            if not Client._disable_sending:
                self.__set_langwatch_exporter(provider)

            if Client._flush_on_exit:
                logger.debug(
                    "Registering atexit handler to flush tracer provider on exit"
                )
                atexit.register(provider.force_flush)

            if Client._debug:
                logger.info(
                    "Successfully configured tracer provider with OTLP exporter"
                )

            return provider
        except Exception as e:
            raise RuntimeError(
                f"Failed to create and configure tracer provider: {e}"
            ) from e

    def __set_langwatch_exporter(self, provider: TracerProvider) -> None:
        provider_id = id(provider)
        if provider_id in Client._exporter_attached_providers:
            if Client._debug:
                logger.debug("LangWatch exporter already attached to this provider, skipping")
            return
        if not Client._api_key:
            raise ValueError("LangWatch API key is required but not provided")

        headers = {
            **build_auth_headers(
                api_key=Client._api_key,
                project_id=Client._project_id,
            ),
            "X-LangWatch-SDK-Version": str(__version__),
        }

        if Client._debug:
            logger.info(
                f"Configuring OTLP exporter with endpoint: {Client._endpoint_url}/api/otel/v1/traces"
            )

        otlp_exporter = OTLPSpanExporter(
            endpoint=f"{Client._endpoint_url}/api/otel/v1/traces",
            headers=headers,
            timeout=int(os.getenv("OTEL_EXPORTER_OTLP_TRACES_TIMEOUT", 30)),
        )

        # Wrap the exporter with conditional logic
        conditional_exporter = ConditionalSpanExporter(
            wrapped_exporter=otlp_exporter,
        )

        processor = FilterableBatchSpanProcessor(
            span_exporter=conditional_exporter,
            exclude_rules=Client._span_exclude_rules,
            max_export_batch_size=int(os.getenv("OTEL_BSP_MAX_EXPORT_BATCH_SIZE", 100)),
            max_queue_size=int(os.getenv("OTEL_BSP_MAX_QUEUE_SIZE", 512)),
            schedule_delay_millis=float(os.getenv("OTEL_BSP_SCHEDULE_DELAY", 1000)),
            export_timeout_millis=float(os.getenv("OTEL_BSP_EXPORT_TIMEOUT", 10000)),
        )
        provider.add_span_processor(processor)
        Client._langwatch_processor = processor
        Client._exporter_attached_providers.add(provider_id)

    def _setup_rest_api_client(self) -> LangWatchApiClient:
        """
        Sets up the REST API client for the client.
        """
        Client._rest_api_client = LangWatchApiClient(
            base_url=Client._endpoint_url,
            headers=build_auth_headers(
                api_key=Client._api_key,
                project_id=Client._project_id,
            ),
            raise_on_unexpected_status=True,
        )

        return Client._rest_api_client


class ConditionalSpanExporter(SpanExporter):
    def __init__(self, wrapped_exporter: SpanExporter):
        self.wrapped_exporter: SpanExporter = wrapped_exporter

    def export(self, spans: Sequence[ReadableSpan]) -> SpanExportResult:
        # Check your singleton's disable flag
        client = get_instance()
        if client and client.disable_sending:
            # Drop all spans - return success without sending
            return SpanExportResult.SUCCESS

        # Normal export
        return self.wrapped_exporter.export(spans)  # type: ignore

    def shutdown(self) -> None:
        return self.wrapped_exporter.shutdown()

    def force_flush(self, timeout_millis: Optional[int] = 30000) -> bool:
        client = get_instance()
        if client and client.disable_sending:
            return True  # Nothing to flush
        # Handle None case by providing default value
        actual_timeout = timeout_millis if timeout_millis is not None else 30000
        return self.wrapped_exporter.force_flush(actual_timeout)

from functools import wraps
from opentelemetry import trace
from opentelemetry.trace import Span
from typing import TYPE_CHECKING, TypeVar, Callable, Any, Optional, Union, Dict
import json

from langwatch.attributes import AttributeKey

if TYPE_CHECKING:
    from langwatch.prompts.prompt import Prompt, CompiledPrompt

T = TypeVar("T", bound="Prompt")


def _set_attribute_if_not_none(
    span: Span, key: str, value: Optional[Union[str, int, float, bool]]
) -> None:
    """Set span attribute only if value is not None."""
    if value is not None:
        span.set_attribute(key, value)


class PromptTracing:
    """Namespace for Prompt method tracing decorators"""

    @staticmethod
    def _set_prompt_attributes(span: Span, prompt: "Prompt") -> None:
        """Set prompt-related attributes on the span."""
        _set_attribute_if_not_none(
            span, AttributeKey.LangWatchPromptId, getattr(prompt, "id", None)
        )
        _set_attribute_if_not_none(
            span, AttributeKey.LangWatchPromptHandle, getattr(prompt, "handle", None)
        )
        _set_attribute_if_not_none(
            span,
            AttributeKey.LangWatchPromptVersionId,
            getattr(prompt, "version_id", None),
        )
        _set_attribute_if_not_none(
            span,
            AttributeKey.LangWatchPromptVersionNumber,
            getattr(prompt, "version", None),
        )

    @staticmethod
    def _create_compile_decorator(
        span_name: str,
    ) -> Callable[[Callable[..., "CompiledPrompt"]], Callable[..., "CompiledPrompt"]]:
        """Internal method to create compile decorators with specified span name"""

        def decorator(
            func: Callable[..., "CompiledPrompt"],
        ) -> Callable[..., "CompiledPrompt"]:
            @wraps(func)
            def wrapper(self: "Prompt", *args: Any, **kwargs: Any) -> "CompiledPrompt":
                with trace.get_tracer(__name__).start_as_current_span(
                    PromptTracing._create_span_name(span_name)
                ) as span:
                    # Set prompt attributes
                    PromptTracing._set_prompt_attributes(span, self)

                    # Create variables dict from args and kwargs
                    variables_dict: Dict[str, Any] = {}
                    if args:
                        first_arg = args[0]
                        if first_arg is not None and hasattr(first_arg, "update"):
                            variables_dict.update(first_arg)
                    variables_dict.update(kwargs)

                    span.set_attribute(
                        AttributeKey.LangWatchPromptVariables,
                        json.dumps(
                            {
                                "type": "json",
                                "value": variables_dict,
                            }
                        ),
                    )

                    try:
                        result = func(self, *args, **kwargs)
                        return result
                    except Exception as ex:
                        span.record_exception(ex)
                        raise

            return wrapper

        return decorator

    @staticmethod
    def compile(
        func: Callable[..., "CompiledPrompt"],
    ) -> Callable[..., "CompiledPrompt"]:
        """Decorator for Prompt.compile method with OpenTelemetry tracing"""
        return PromptTracing._create_compile_decorator("compile")(func)

    @staticmethod
    def compile_strict(
        func: Callable[..., "CompiledPrompt"],
    ) -> Callable[..., "CompiledPrompt"]:
        """Decorator for Prompt.compile_strict method with OpenTelemetry tracing"""
        return PromptTracing._create_compile_decorator("compile_strict")(func)

    @staticmethod
    def _create_span_name(span_name: str) -> str:
        """Create a span name for the prompt"""
        return f"Prompt.{span_name}"


prompt_tracing = PromptTracing()
